// Lit un message /test et en fait une campagne prete pour le sous-workflow.
// Format attendu (une ligne par cas, attendu facultatif en mode open) :
//   /test [exact|judge|open]
//   <le prompt, sur une ou plusieurs lignes>
//   cases:
//   entree => attendu
const msg = $('Message recu').first().json.message || {};
const chatId = msg.chat ? msg.chat.id : null;
const lignes = String(msg.text || '').replace(/\r/g, '').split('\n');
const tete = lignes[0].trim().split(/\s+/);
const ALIAS = { exact: 'exact', judge: 'juge', juge: 'juge', open: 'libre', libre: 'libre' };
let mode = ALIAS[(tete[1] || '').toLowerCase()] || '';

const reste = lignes.slice(1);
const iCas = reste.findIndex(l => /^\s*(cases?|cas)\s*:/i.test(l));
const lignesPrompt = iCas === -1 ? reste : reste.slice(0, iCas);
const prompt = lignesPrompt.join('\n').replace(/^\s*prompt\s*:\s*/i, '').trim();
const cas = (iCas === -1 ? [] : reste.slice(iCas + 1))
  .map(l => l.trim()).filter(Boolean)
  .map(l => { const k = l.indexOf('=>'); return k === -1 ? { entree: l, attendu: '' } : { entree: l.slice(0, k).trim(), attendu: l.slice(k + 2).trim() }; })
  .filter(c => c.entree);

if (!mode) mode = cas.length && cas.every(c => c.attendu) ? 'exact' : 'libre';

const MAX_CAS = 8;
let erreur = '';
if (!prompt) erreur = 'Your message has no prompt.';
else if (!cas.length) erreur = 'Your message has no test case. Add a line "cases:" followed by one case per line.';
else if (cas.length > MAX_CAS) erreur = 'At most ' + MAX_CAS + ' cases per run from Telegram (free Groq quota). Use the website for bigger runs.';
else if (mode !== 'libre' && cas.some(c => !c.attendu)) erreur = 'With exact or judge scoring, every case needs an expected answer: input => expected.';

const repetitions = 3;
const temperature = 0.7;
const campagneId = 'camp_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7);
const runs = [];
if (!erreur) cas.forEach((c, i) => {
  for (let r = 1; r <= repetitions; r++) {
    runs.push({ campagneId, casId: 'cas_' + (i + 1), entree: c.entree, attendu: mode === 'libre' ? '' : c.attendu, repetition: r, mode, prompt, temperature });
  }
});
// Duree estimee : espacement des appels (2,5 s execution, 6 s juge) + pause et reviseur.
const secondes = runs.length * (mode === 'exact' ? 2.5 : 8.5) + 45;

return [{ json: {
  valide: !erreur,
  erreur,
  chatId,
  campagneId,
  nom: 'Telegram: ' + prompt.split('\n')[0].slice(0, 50),
  prompt,
  mode,
  temperature,
  repetitions,
  nbCas: cas.length,
  nbAppels: runs.length,
  minutes: Math.max(1, Math.round(secondes / 60)),
  runs
} }];

// Met en forme le resume renvoye par le sous-workflow pour Telegram (HTML).
const r = $input.first().json;
const chatId = $('Analyser le /test').first().json.chatId;
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const tronc = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n) + '…' : s; };
const MODE = { exact: 'exact', juge: 'judge', libre: 'open' };
const ICONE = { reussi: '✅', instable: '⚠️', echec: '❌' };

const lignes = [];
lignes.push('<b>Prompt Bench, run ' + esc(String(r.campagneId || '').slice(-4).toUpperCase()) + '</b> (' + (MODE[r.mode] || r.mode) + ' scoring)');
lignes.push('Pass rate: <b>' + r.tauxReussite + ' %</b> (' + r.totalReussites + '/' + r.totalAppels + ' calls)');
lignes.push('Unstable cases: ' + r.casInstables + ' · Failing cases: ' + r.casEchoues);
if (typeof r.coutParAppel === 'number') lignes.push('Cost of one production call: $' + r.coutParAppel.toFixed(6) + (r.coutEstime ? ' (estimated)' : ''));
lignes.push('');
(r.cas || []).forEach(c => lignes.push((ICONE[c.statut] || '•') + ' ' + esc(tronc(c.entree, 60)) + ': ' + c.reussites + '/' + c.total));
if (r.diagnostic) { lignes.push(''); lignes.push('<b>Diagnosis</b>'); lignes.push(esc(tronc(r.diagnostic, 700))); }
let texte = lignes.join('\n');
if (r.promptCorrige) {
  const reste = 3900 - texte.length - 60;
  texte += '\n\n<b>Fixed prompt</b>\n<pre>' + esc(tronc(r.promptCorrige, Math.max(200, reste))) + '</pre>';
}
return [{ json: { chatId, texte } }];

// Les cinq dernieres campagnes, lues dans l onglet campagnes du Google Sheet.
const chatId = $('Message recu').first().json.message.chat.id;
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const STATUT = { termine: '✅ done', 'en cours': '⏳ running', erreur: '❌ error' };
const lignes = $input.all().map(i => i.json).filter(c => c['Campagne ID']).slice(-5).reverse();
let texte;
if (!lignes.length) {
  texte = 'No run yet. Send /test to start one.';
} else {
  texte = '<b>Last ' + lignes.length + ' runs</b>\n\n' + lignes.map(c => {
    const date = String(c['Date'] || '').slice(0, 16).replace('T', ' ');
    const taux = c['Taux reussite'] !== '' && c['Taux reussite'] != null ? ' · ' + c['Taux reussite'] + ' %' : '';
    return (STATUT[c['Statut']] || esc(c['Statut'])) + taux + '\n' + esc(String(c['Nom'] || '').slice(0, 60)) + ' · ' + date;
  }).join('\n\n');
}
return [{ json: { chatId, texte } }];
